import{t as e}from"./buildPage-DWQZYYcs.js";var t=e({slug:`presentation-builder`,heroTitle:`Build your presentation in minutes`,heroSubtitle:`Perplexity Computer researches your topic, structures your narrative, and delivers a polished slide deck — automatically.`,inputUrlCta:`Build my deck`,inputUrlPlaceholder:`e.g. topic or URL`,inputUrlPrefill:`Go to {url} and build a professional presentation based on the content found there. 1) Analyze the page to extract the core topic, key data points, arguments, and supporting evidence. 2) Research additional sources to strengthen the narrative with up-to-date statistics and industry context. 3) Create a structured slide outline with a compelling opening hook, clear section breaks, and a strong closing CTA. 4) Write concise slide copy for each slide — one key idea per slide, bullet points under 8 words each, speaker notes with talking points. 5) Suggest data visualizations, charts, and imagery for each slide. 6) Deliver the full presentation in a structured format with: slide number, title, body copy, speaker notes, and visual direction for every slide.`,heroOverlaySteps:[`Extracting key topics, data points, and narrative structure`,`Researching supporting stats, examples, and industry context`,`Writing slide copy, speaker notes, and visual direction for each slide`,`Complete slide deck with speaker notes and visuals — ready to present`],generatingSteps:[`Visiting {url} to extract your topic, key arguments, and supporting data`,`Designing an agent to research additional sources and strengthen your narrative`,`Configuring slide structure, copy generation, and visual recommendations`,`Setting up your deliverable deck with speaker notes and design direction`],featureSectionTitle:`From topic to polished deck`,featureCardTitles:[`Connects to your productivity stack`,`Outputs you can present`],featureCardDescriptions:[`Computer breaks your project into tasks, spins up specialized agents, and matches each one to the AI model that does it best.`,`Google Slides, Google Drive, Notion, Canva, Dropbox Sign — Computer plugs into your tools so your deck flows from research to finished slides in one workflow.`,`Structured slide outlines. Concise bullet copy. Speaker notes with talking points. Data visualization suggestions. Design direction for every slide.`],capabilitySectionTitle:`Your presentation team, on autopilot`,capabilitySectionSubtitle:`Paste your topic, step away, come back to a presentation-ready deck.`,capabilityCards:[{title:`Topic Research`,description:`Computer can analyze your source material and pull in supporting stats, case studies, and industry data — so every slide is backed by evidence.`},{title:`Narrative Structure`,description:`Computer can build a clear story arc — opening hook, logical sections, data-driven arguments, and a closing CTA that lands.`},{title:`Slide Copy & Notes`,description:`Computer can write concise slide text and detailed speaker notes — one idea per slide, tight bullets, and talking points you can rehearse from.`},{title:`Connect Your Tools`,description:`Computer can push your deck to Google Drive, Notion, and Canva — build workflows across your entire productivity and design stack.`},{title:`Learns Your Style`,description:`Computer can remember your brand voice, preferred slide structure, and past decks — so every presentation stays consistent with your standards.`},{title:`Version Tracking`,description:`Computer can monitor source data for updates and alert you when key stats change — so your deck never goes stale before the big meeting.`}]});export{t as default};
